def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_last, opp_last = history[-1]

    if n < 6:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'

    # Immediate but bounded retaliation
    if opp_last == 'D' and my_last == 'C':
        return 'D'
    if opp_last == 'D' and my_last == 'D':
        recent_opp_d = sum(1 for a, b in history[-3:] if b == 'D')
        if recent_opp_d >= 3:
            if opp_d >= n - 2:
                return 'D'
            return 'C' if rng.random() < 0.22 else 'D'
        return 'D'

    # opp_last == 'C'
    window = 10 if n >= 10 else n
    recent_opp_c = sum(1 for a, b in history[-window:] if b == 'C')
    recent_rate = recent_opp_c / window

    # Endgame exploitation against very cooperative opponents
    if n >= 94:
        if opp_c >= n - 4:
            if n >= 96:
                return 'D'
            return 'D' if rng.random() < 0.7 else 'C'
        if recent_rate >= 0.9:
            return 'D' if rng.random() < 0.35 else 'C'
        return 'C'

    # Mostly-cooperative opponent: maintain cooperation, rare probing
    if opp_c >= int(0.82 * n):
        if my_last == 'D' and rng.random() < 0.5:
            return 'C'
        if n >= 40 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Sustained defector: defend
    if opp_d >= int(0.7 * n) and recent_rate < 0.4:
        if recent_rate < 0.2:
            return 'D'
        return 'C' if rng.random() < 0.12 else 'D'

    # Mixed: tit-for-tat with forgiveness after mutual defection
    if recent_rate >= 0.75:
        return 'C'
    if recent_rate >= 0.45:
        if my_last == 'D' and rng.random() < 0.55:
            return 'C'
        return 'C' if rng.random() < 0.85 else 'D'
    if my_last == 'D' and rng.random() < 0.35:
        return 'C'
    return 'D' if rng.random() < 0.75 else 'C'
